func (g *gitlab) GetFile(ctx context.Context, repositoryURL string, ref string, path string) ([]byte, error) {
	// get the namespace and project name
	namespaceAndPath, err := repositoryURLToNamespaceAndPath(repositoryURL)
	if err != nil {
		return nil, err
	}

	file, _, err := g.tokenClient.RepositoryFiles.GetFile(namespaceAndPath, path, &client.GetFileOptions{
		Ref: common.Ptr(ref),
	}, client.WithContext(ctx))

	if err != nil {
		return nil, errors.New(fmt.Sprintf("getFile returned error: %s", err.Error()))
	}

	// log.Printf("[GITLAB HTTP RESPONSE] File: %s / Commit ID: %s\n", file.FileName, file.CommitID)

	return base64.StdEncoding.DecodeString(file.Content)
}

func splitGitLabURL(URL string) (string, string, string, error) {
	// Define the regex to extract repo path, branch name, and file path
	re := regexp.MustCompile(`^(https?://.+?)/-/raw/([^/]+)/(.*)$`)

	matches := re.FindStringSubmatch(URL)
	if len(matches) != 4 {
		return "", "", "", fmt.Errorf("invalid URL format")
	}

	return matches[1], matches[2], matches[3], nil
}

func (g *gitlab) GetFileFromRawURL(ctx context.Context, rawURL string) ([]byte, error) {
	// split the raw URL into repository URL, path and ref
	// example: https://gitlab.opencode.de/open-code/badgebackend/badge-api/-/raw/main/.gitignore
	// split into: https://gitlab.opencode.de/open-code/badgebackend/badge-api, main, .gitignore
	repoURL, ref, path, err := splitGitLabURL(rawURL)
	if err != nil {
		return nil, errors.Wrap(err, "failed to split gitlab URL")
	}

	return g.GetFile(ctx, repoURL, ref, path)
}

